extends SceneTree

func _initialize() -> void:
	call_deferred("run_test")

func run_test() -> void:
	var scene = load("res://main.tscn").instantiate()
	root.add_child(scene)
	current_scene = scene
	scene.start()
	for i in range(600):
		scene._process(0.01667)
		if i % 70 == 0:
			scene.jump()
		if i % 120 == 0:
			scene.lane = (i / 120) % 3 - 1
	scene.start()
	await process_frame
	quit()
